import sympy.simplify.tests.test_sqrtdenest as t
import sympy
from sympy import sqrt, I

failures = []
for name in dir(t):
    if name.startswith('test_'):
        func = getattr(t, name)
        if getattr(func, '_slow', False):
            print('SKIP slow:', name)
            continue
        try:
            func()
            print('PASS', name)
        except Exception as e:
            failures.append((name, e))
            print('FAIL', name, e)

# New scenario from PR
try:
    expr = (3 - sqrt(2)*sqrt(4 + 3*I) + 3*I)/2
    out = sympy.sqrtdenest(expr)
    print('PR expr:', repr(expr))
    print('PR sqrtdenest:', repr(out))
    # It should not raise and should be mathematically unchanged-equivalent; no exact assertion beyond no raise
except Exception as e:
    print('PR FAIL', e)
    failures.append(('PR scenario', e))

print('FAILURES:', failures)
raise SystemExit(1 if failures else 0)
